(2081928, 283699, 51210, '<td valign="top">I would love to be there... meaning, this is Adams style... nice work!</td>', 'I would love to be there... meaning, this is Adams style... nice work!', '2006-01-25 08:50:48.000000', NULL, 1),
(2081930, 285423, 15711, '<td valign="top">I think it would look more like one of his photos if it were wide angle and had a bit more contrast. As it is, it''s just kind of this mountain dead centered in the shot.  If done from a side perspective, you''d get more interesting snow and trees.</td>', 'I think it would look more like one of his photos if it were wide angle and had a bit more contrast. As it is, it''s just kind of this mountain dead centered in the shot.  If done from a side perspective, you''d get more interesting snow and trees.', '2006-01-25 08:51:10.000000', NULL, 1),
(2081932, 284196, 15711, '<td valign="top">Really good.  Love the contemporary sense of it.</td>', 'Really good.  Love the contemporary sense of it.', '2006-01-25 08:51:59.000000', NULL, 1),
(2081933, 284661, 49109, '<td valign="top">light is too harsh, collar is blown, shadow distracts</td>', 'light is too harsh, collar is blown, shadow distracts', '2006-01-25 08:52:30.000000', NULL, 1),
(2081934, 285622, 51210, '<td valign="top">Hey I live near Buffalo!</td>', 'Hey I live near Buffalo!', '2006-01-25 08:52:41.000000', NULL, 1),
(2081935, 285747, 15711, '<td valign="top">Excellent title.  I like how his eyes jump out of the page.  The leading line of the silvery zipper really draws you to his face.  Great tribute to Dorothea too!</td>', 'Excellent title.  I like how his eyes jump out of the page.  The leading line of the silvery zipper really draws you to his face.  Great tribute to Dorothea too!', '2006-01-25 08:52:42.000000', NULL, 1),
