INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2081950, 285632, 51210, '<td valign="top">Ouch!</td>', 'Ouch!', '2006-01-25 08:55:58.000000', NULL, 1),
(2081951, 285622, 15711, '<td valign="top">I think in order for this to look like Avedon, it needs much more contrast and perhaps a sense of purpose.  As it is, it just kind of looks like a guy in a windbreaker. Does that make sense? Avedon''s stuff caught people in the act of doing what they do (ie: a singer singing, a chef with a chef hat on, etc.) I think this might have a bit better impact too if it wasn''t so centered.</td>', 'I think in order for this to look like Avedon, it needs much more contrast and perhaps a sense of purpose.  As it is, it just kind of looks like a guy in a windbreaker. Does that make sense? Avedon''s stuff caught people in the act of doing what they do (ie: a singer singing, a chef with a chef hat on, etc.) I think this might have a bit better impact too if it wasn''t so centered.', '2006-01-25 08:56:13.000000', NULL, 1),
(2081954, 285761, 49109, '<td valign="top">not white enough and lots of artefacts around the blossom (and in top left corner) from improper darkening of the background in PS</td>', 'not white enough and lots of artefacts around the blossom (and in top left corner) from improper darkening of the background in PS', '2006-01-25 08:56:31.000000', NULL, 1),
(2081956, 285519, 15711, '<td valign="top">Really good.  I like this alot.  Very well done with the contrast and perspective. 8</td>', 'Really good.  I like this alot.  Very well done with the contrast and perspective. 8', '2006-01-25 08:56:40.000000', NULL, 1),
(2081958, 285602, 15711, '<td valign="top">I don''t recognize a photographer''s style, but that doesn''t mean anything.  Love the eyes and the DOF.  Interesting use of desaturation. 7</td>', 'I don''t recognize a photographer''s style, but that doesn''t mean anything.  Love the eyes and the DOF.  Interesting use of desaturation. 7', '2006-01-25 08:57:28.000000', NULL, 1),
(2081961, 285338, 15711, '<td valign="top">I think in order for this to look like his work, it needs to be in color and have that "neat image" sense to it.  But having said that, this is an excellent portrait. I love the light and shadow (similar to his). The eyes are great and the detail of the tiny hairs on his face work, as it''s a child.  Good job.</td>', 'I think in order for this to look like his work, it needs to be in color and have that "neat image" sense to it.  But having said that, this is an excellent portrait. I love the light and shadow (similar to his). The eyes are great and the detail of the tiny hairs on his face work, as it''s a child.  Good job.', '2006-01-25 08:59:20.000000', NULL, 1),
(2081963, 285761, 15711, '<td valign="top">Beautiful.  Simple and very emotive.  Well done.</td>', 'Beautiful.  Simple and very emotive.  Well done.', '2006-01-25 09:00:03.000000', NULL, 1),
(2081966, 283852, 15711, '<td valign="top">Sally''s photos have much more of a gutsy sense to them in my opnion.  The eyes are good, but it seems too blurred and soft to really look like one of hers.</td>', 'Sally''s photos have much more of a gutsy sense to them in my opnion.  The eyes are good, but it seems too blurred and soft to really look like one of hers.', '2006-01-25 09:01:29.000000', NULL, 1),
(2081970, 283627, 15711, '<td valign="top">Absolutely stunning.  The lighting on his nose in combination with the fur hat.  But you know what really does it for me?  The teal green shirt.  Something about it''s color value that just sets it off!  WOW - 10</td>', 'Absolutely stunning.  The lighting on his nose in combination with the fur hat.  But you know what really does it for me?  The teal green shirt.  Something about it''s color value that just sets it off!  WOW - 10', '2006-01-25 09:02:59.000000', NULL, 1),
(2081971, 283617, 49109, '<td valign="top">perfect!</td>', 'perfect!', '2006-01-25 09:03:03.000000', NULL, 1),
(2081974, 285425, 32133, '<td valign="top">I love this pix.  Great vantage point and lighting.  10</td>', 'I love this pix.  Great vantage point and lighting.  10', '2006-01-25 09:04:34.000000', NULL, 1),
(2081975, 283630, 15711, '<td valign="top">This looks nothing like a Geddes.  Hers were tack sharp and she had a use of props to make her babies look like peas, flowers, etc. The colors were rich and vibrant and they are normally done in a studio setting. Usually she uses newborns as well. Sorry, this just looks like a snapshot of a cute baby.</td>', 'This looks nothing like a Geddes.  Hers were tack sharp and she had a use of props to make her babies look like peas, flowers, etc. The colors were rich and vibrant and they are normally done in a studio setting. Usually she uses newborns as well. Sorry, this just looks like a snapshot of a cute baby.', '2006-01-25 09:04:58.000000', NULL, 1),
(2081977, 284916, 15711, '<td valign="top">Hmmm - who''s the photographer you''re attributing this to?  <br/> <br/>I do like it''s quirky "off the wall" subject matter. The lighting is a tad harsh.</td>', 'Hmmm - who''s the photographer you''re attributing this to?   I do like it''s quirky "off the wall" subject matter. The lighting is a tad harsh.', '2006-01-25 09:05:59.000000', NULL, 1),
(2081981, 285354, 15711, '<td valign="top">Nice one.  It would be perfect if you couldn''t see the diaper. Beautiful baby and the lighting is nice.  Good quality to the skintones as well.</td>', 'Nice one.  It would be perfect if you couldn''t see the diaper. Beautiful baby and the lighting is nice.  Good quality to the skintones as well.', '2006-01-25 09:07:17.000000', NULL, 1),
(2081983, 285425, 15711, '<td valign="top">Nice! I like the rich tones of the filter. Good perspective.</td>', 'Nice! I like the rich tones of the filter. Good perspective.', '2006-01-25 09:07:47.000000', NULL, 1),
(2081984, 284031, 15711, '<td valign="top">AWWWW  This is great.  Not familiar with Jim''s work.  I''ll have to check it out. hee hee</td>', 'AWWWW  This is great.  Not familiar with Jim''s work.  I''ll have to check it out. hee hee', '2006-01-25 09:08:31.000000', NULL, 1),
(2081989, 285575, 15711, '<td valign="top">Nicely posed like the original.  The lighting is a tad harsh on the face.  Maybe a slight brown tinge to it would look better.  Not crazy about the texture on the wall. The composition is good.  The eye is good.</td>', 'Nicely posed like the original.  The lighting is a tad harsh on the face.  Maybe a slight brown tinge to it would look better.  Not crazy about the texture on the wall. The composition is good.  The eye is good.', '2006-01-25 09:11:30.000000', NULL, 1),
(2081993, 285117, 32133, '<td valign="top">Beautiful crisp shot. 10</td>', 'Beautiful crisp shot. 10', '2006-01-25 09:12:02.000000', NULL, 1),
(2081994, 283468, 49109, '<td valign="top">good portrait, but not sharp enough, highlights burnt</td>', 'good portrait, but not sharp enough, highlights burnt', '2006-01-25 09:12:48.000000', NULL, 1),
(2081996, 285117, 15711, '<td valign="top">This is great.  Very late 40''s - early 50''s.  Love the filter you chose.  The floor pattern is a bit distracting, but overall - well done.</td>', 'This is great.  Very late 40''s - early 50''s.  Love the filter you chose.  The floor pattern is a bit distracting, but overall - well done.', '2006-01-25 09:13:13.000000', NULL, 1),
