(2082123, 285312, 15711, '<td valign="top">Absolutely beautiful.  I need to look up his work.  This is gorgeous with the oversaturated colors.</td>', 'Absolutely beautiful.  I need to look up his work.  This is gorgeous with the oversaturated colors.', '2006-01-25 09:55:45.000000', NULL, 1),
