(2082128, 284028, 43753, '<td valign="top">Awesome! I really like that the petals retain a sort of silky delicacy even with the sharp outlines. Great work.</td>', 'Awesome! I really like that the petals retain a sort of silky delicacy even with the sharp outlines. Great work.', '2006-01-25 09:56:10.000000', NULL, 1),
(2082133, 283739, 43753, '<td valign="top">Very nicely put together. Your colors are thought out and coordinated perfectly. I like the softness of the skin and the perspective you show.</td>', 'Very nicely put together. Your colors are thought out and coordinated perfectly. I like the softness of the skin and the perspective you show.', '2006-01-25 09:57:09.000000', NULL, 1),
(2082138, 284031, 43753, '<td valign="top">Awe! How cute. I like this light hearted pose. It''s like the little pug is pleading - "Please feed me". Great sepia, wish there was just a tad more contrast.</td>', 'Awe! How cute. I like this light hearted pose. It''s like the little pug is pleading - "Please feed me". Great sepia, wish there was just a tad more contrast.', '2006-01-25 09:58:25.000000', NULL, 1),
(2082141, 285580, 43753, '<td valign="top">Very natural, candid shot with a photojournalistic feel to it.</td>', 'Very natural, candid shot with a photojournalistic feel to it.', '2006-01-25 09:59:30.000000', NULL, 1),
(2082144, 285008, 43753, '<td valign="top">I think your framing with the tree on the right really makes the difference with this image. Great DOF. Lots of detail.</td>', 'I think your framing with the tree on the right really makes the difference with this image. Great DOF. Lots of detail.', '2006-01-25 10:00:22.000000', NULL, 1),
(2082150, 285423, 43753, '<td valign="top">Nice shot. I would like to see a bit more contrast though.</td>', 'Nice shot. I would like to see a bit more contrast though.', '2006-01-25 10:01:08.000000', NULL, 1),
(2082153, 284470, 43753, '<td valign="top">Very chic. I love the dark contrast and the sexy line of the leg. Excellent.</td>', 'Very chic. I love the dark contrast and the sexy line of the leg. Excellent.', '2006-01-25 10:01:51.000000', NULL, 1),
(2082156, 284907, 43753, '<td valign="top">Great moment with wonderful composition.</td>', 'Great moment with wonderful composition.', '2006-01-25 10:02:46.000000', NULL, 1),
