(2082161, 285287, 43753, '<td valign="top">Very smooth and sexy. I would like athe glass a little more level and maybe a wider angle.</td>', 'Very smooth and sexy. I would like athe glass a little more level and maybe a wider angle.', '2006-01-25 10:04:08.000000', NULL, 1),
(2082163, 284164, 43753, '<td valign="top">Great cityscape with excellent lines.</td>', 'Great cityscape with excellent lines.', '2006-01-25 10:04:47.000000', NULL, 1),
(2082165, 283576, 43753, '<td valign="top">Colorful and nicely composed. I love the lighting and the background.</td>', 'Colorful and nicely composed. I love the lighting and the background.', '2006-01-25 10:05:14.000000', NULL, 1),
(2082168, 285312, 43753, '<td valign="top">Beautiful, almost surreal sky. Great color, excellent composition.</td>', 'Beautiful, almost surreal sky. Great color, excellent composition.', '2006-01-25 10:05:42.000000', NULL, 1),
(2082170, 283159, 43753, '<td valign="top">My favorite so far. So delicate and soft. The tones are perfect.</td>', 'My favorite so far. So delicate and soft. The tones are perfect.', '2006-01-25 10:06:06.000000', NULL, 1),
(2082173, 285575, 43753, '<td valign="top">Great B&amp;W portrait with perfect noise. Love the side of face in the dark and the outline of the nose and mouth.</td>', 'Great B&W portrait with perfect noise. Love the side of face in the dark and the outline of the nose and mouth.', '2006-01-25 10:07:01.000000', NULL, 1),
(2082176, 285631, 43753, '<td valign="top">I like your idea, but would like to see more contrast and grain.</td>', 'I like your idea, but would like to see more contrast and grain.', '2006-01-25 10:07:40.000000', NULL, 1),
(2082178, 285572, 43753, '<td valign="top">Different shot. I like the color and the hint of landscape in the background.</td>', 'Different shot. I like the color and the hint of landscape in the background.', '2006-01-25 10:08:21.000000', NULL, 1),
(2082179, 285594, 43753, '<td valign="top">Very simpl eand stark. Nice clean white background. Interesting lighting to highlight the brow neck and chin.</td>', 'Very simpl eand stark. Nice clean white background. Interesting lighting to highlight the brow neck and chin.', '2006-01-25 10:09:10.000000', NULL, 1),
(2082180, 285492, 43410, '<td valign="top">Great picture.  Love the execution.  Will not count off for it, but i believe a more definite edge around the "face" would be more effective.  but this does not take away from this wonderful image.  great job. 8</td>', 'Great picture.  Love the execution.  Will not count off for it, but i believe a more definite edge around the "face" would be more effective.  but this does not take away from this wonderful image.  great job. 8', '2006-01-25 10:09:45.000000', NULL, 1),
(2082181, 283584, 43753, '<td valign="top">I like the shadows from the legs and the hint of buttock. Maybe a tighter crop to rid the right side of the frame from too much light.</td>', 'I like the shadows from the legs and the hint of buttock. Maybe a tighter crop to rid the right side of the frame from too much light.', '2006-01-25 10:10:23.000000', NULL, 1),
(2082184, 285732, 43753, '<td valign="top">Avedon is one of my favorites. I like your take on this particular style. Well done.</td>', 'Avedon is one of my favorites. I like your take on this particular style. Well done.', '2006-01-25 10:10:58.000000', NULL, 1),
(2082185, 283628, 43753, '<td valign="top">I think you did well to capture an old feel to the image. Excellent soft fadng around the frame.</td>', 'I think you did well to capture an old feel to the image. Excellent soft fadng around the frame.', '2006-01-25 10:11:25.000000', NULL, 1),
(2082186, 283627, 6388, '<td valign="top">i see how it is...that little prick lawrence''s opinion means more than mine now, huh?</td>', 'i see how it is...that little prick lawrence''s opinion means more than mine now, huh?', '2006-01-25 10:11:31.000000', NULL, 1),
