(2083126, 283895, 31812, '<td valign="top">This is a little too dark for me.</td>', 'This is a little too dark for me.', '2006-01-25 14:09:39.000000', NULL, 1),
(2083130, 285241, 31812, '<td valign="top">Very nice. I think you nailed this.</td>', 'Very nice. I think you nailed this.', '2006-01-25 14:09:58.000000', NULL, 1),
(2083154, 284028, 31812, '<td valign="top">Beautiful shot. I think the outline of the lilies at the top are a little too abrupt. I like the natural fade at the bottom, however this is really beautiful.</td>', 'Beautiful shot. I think the outline of the lilies at the top are a little too abrupt. I like the natural fade at the bottom, however this is really beautiful.', '2006-01-25 14:12:17.000000', NULL, 1),
(2083167, 285312, 31812, '<td valign="top">This is beautifully intense. The blue in the sky''s a little distracting to me, but I love the water capture. Great shot.</td>', 'This is beautifully intense. The blue in the sky''s a little distracting to me, but I love the water capture. Great shot.', '2006-01-25 14:14:27.000000', NULL, 1),
(2083196, 284447, 31812, '<td valign="top">There''s a bit too much whitespace in this picture for me, but I like what you were trying to do.</td>', 'There''s a bit too much whitespace in this picture for me, but I like what you were trying to do.', '2006-01-25 14:21:07.000000', NULL, 1),
(2083299, 284969, 40718, '<td valign="top">Looks a bit nippy.;)  The pose seems right up his alley. Well done.</td>', 'Looks a bit nippy.;)  The pose seems right up his alley. Well done.', '2006-01-25 14:43:11.000000', NULL, 1),
(2083307, 283628, 40718, '<td valign="top">great sepia work.</td>', 'great sepia work.', '2006-01-25 14:44:40.000000', NULL, 1),
(2083311, 285694, 40718, '<td valign="top">Looks a little too sharp around the arms and shoulder.  Could have used a history brush on that.  Great pose and composition.</td>', 'Looks a little too sharp around the arms and shoulder.  Could have used a history brush on that.  Great pose and composition.', '2006-01-25 14:45:46.000000', NULL, 1),
(2083316, 284990, 40718, '<td valign="top">Neill''s work seems to be a juxtaposition of red AND blue.  This is a nice sunset though.</td>', 'Neill''s work seems to be a juxtaposition of red AND blue.  This is a nice sunset though.', '2006-01-25 14:46:39.000000', NULL, 1),
(2083321, 285635, 40718, '<td valign="top">nice attempt at voluminous light.  To bad you don''t have a subject "in the light". Still, I see the emulation.</td>', 'nice attempt at voluminous light.  To bad you don''t have a subject "in the light". Still, I see the emulation.', '2006-01-25 14:47:51.000000', NULL, 1),
(2083322, 284836, 15711, '<td valign="top">Great idea putting the link!!  Nicely done.  Love the starkness.  Nice contrast.</td>', 'Great idea putting the link!!  Nicely done.  Love the starkness.  Nice contrast.', '2006-01-25 14:48:01.000000', NULL, 1),
(2083328, 285594, 40718, '<td valign="top">should have cropped vertically.  Great blank stare.  Looks like you need just a tad more DOF for focus.</td>', 'should have cropped vertically.  Great blank stare.  Looks like you need just a tad more DOF for focus.', '2006-01-25 14:49:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2083331, 285748, 15711, '<td valign="top">Richard Avedon''s work is legendary - he is one of my favorites.  I like your tribute to him. I wonder if the contrast is more that he would do, but I like your version of the bassist and guitar player.</td>', 'Richard Avedon''s work is legendary - he is one of my favorites.  I like your tribute to him. I wonder if the contrast is more that he would do, but I like your version of the bassist and guitar player.', '2006-01-25 14:49:53.000000', NULL, 1),
(2083332, 285117, 40718, '<td valign="top">I''m having so much fun voting this challenge.  Great composition.  Perfect tonality. 8 for now...</td>', 'I''m having so much fun voting this challenge.  Great composition.  Perfect tonality. 8 for now...', '2006-01-25 14:50:15.000000', NULL, 1),
(2083339, 285672, 15711, '<td valign="top">So beautiful.  The bare braches are like lace! The placement of the main tree is perfect so that you eye can follow to the hills in the background.  Great job!! Love the filter and it certainly is a fine tribute to Kouklis.</td>', 'So beautiful.  The bare braches are like lace! The placement of the main tree is perfect so that you eye can follow to the hills in the background.  Great job!! Love the filter and it certainly is a fine tribute to Kouklis.', '2006-01-25 14:51:18.000000', NULL, 1),
(2083343, 284540, 40718, '<td valign="top">Warhol?</td>', 'Warhol?', '2006-01-25 14:51:28.000000', NULL, 1),
(2083358, 285735, 40718, '<td valign="top">I love the word ephemeral. :)  Seems just a tad posed for Doisneau (at least his famous shot).  Still wonderfully done. 7</td>', 'I love the word ephemeral. :)  Seems just a tad posed for Doisneau (at least his famous shot).  Still wonderfully done. 7', '2006-01-25 14:54:01.000000', NULL, 1),
(2083361, 283617, 15711, '<td valign="top">Very Weston-esque with his love of inanimate objects.  Great choice.  I like the detail of the decayed skull against the intricacies of the leaves and dead branches although I''m thinking his shot might have had a solid black background.  The filter color is perfect. 8</td>', 'Very Weston-esque with his love of inanimate objects.  Great choice.  I like the detail of the decayed skull against the intricacies of the leaves and dead branches although I''m thinking his shot might have had a solid black background.  The filter color is perfect. 8', '2006-01-25 14:54:12.000000', NULL, 1),
(2083367, 284418, 15711, '<td valign="top">Quite lovely with the textural variants of the stone and the flower.  THe lighting is well done too. The crop at the top seems a tad tight to me.</td>', 'Quite lovely with the textural variants of the stone and the flower.  THe lighting is well done too. The crop at the top seems a tad tight to me.', '2006-01-25 14:54:52.000000', NULL, 1),
(2083386, 283972, 15711, '<td valign="top">One of the better landscapes in this challenge.  I figured we''d see lots of Adams tributes and this one is excellent.  The angle of the shot; the leading line of the "stepping stones," but mostly the vista view and deep contrast.  Just exactly what he''d do.  Great image 9</td>', 'One of the better landscapes in this challenge.  I figured we''d see lots of Adams tributes and this one is excellent.  The angle of the shot; the leading line of the "stepping stones," but mostly the vista view and deep contrast.  Just exactly what he''d do.  Great image 9', '2006-01-25 14:56:39.000000', NULL, 1),
(2083394, 285641, 15711, '<td valign="top">Lovely image.  The sky color of deep cobalt is very pleasing.  Love the reaching of the trees - til they touch. Nicely done.</td>', 'Lovely image.  The sky color of deep cobalt is very pleasing.  Love the reaching of the trees - til they touch. Nicely done.', '2006-01-25 14:58:05.000000', NULL, 1),
