(2091309, 283382, 31443, '<td valign="top">This could be so many to attribute to, lovely photograph..</td>', 'This could be so many to attribute to, lovely photograph..', '2006-01-27 06:16:07.000000', NULL, 1),
(2091311, 284470, 31443, '<td valign="top">Nice textures you´ve brought out..</td>', 'Nice textures you´ve brought out..', '2006-01-27 06:17:14.000000', NULL, 1),
(2091313, 285524, 31443, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-01-27 06:18:45.000000', NULL, 1),
(2091373, 284690, 16148, '<td valign="top">Interesting grouping of objects and nice tones.  Good luck!</td>', 'Interesting grouping of objects and nice tones.  Good luck!', '2006-01-27 06:40:39.000000', NULL, 1),
