(2091409, 285758, 16148, '<td valign="top">Nice image of a common everyday object who''s beauty goes unnoticed.</td>', 'Nice image of a common everyday object who''s beauty goes unnoticed.', '2006-01-27 07:12:22.000000', NULL, 1),
