(2091789, 285733, 49489, '<td valign="top">Ansel</td>', 'Ansel', '2006-01-27 10:21:39.000000', NULL, 1),
(2091821, 285735, 34659, '<td valign="top">Beautiful job.  I think Doisneau would be flattered.</td>', 'Beautiful job.  I think Doisneau would be flattered.', '2006-01-27 10:42:14.000000', NULL, 1),
(2091822, 285759, 34659, '<td valign="top">Haunting...  Scary really...  Great job.  Looking forward to reading how you accomplished this.</td>', 'Haunting...  Scary really...  Great job.  Looking forward to reading how you accomplished this.', '2006-01-27 10:42:42.000000', NULL, 1),
(2091823, 284836, 34659, '<td valign="top">This is really good.  Great job.  The expression, the pose, the lighting - all top notch.</td>', 'This is really good.  Great job.  The expression, the pose, the lighting - all top notch.', '2006-01-27 10:42:50.000000', NULL, 1),
(2091845, 285748, 43753, '<td valign="top">Very strong black and white. Almost too contrasty though. There is some detail lost.</td>', 'Very strong black and white. Almost too contrasty though. There is some detail lost.', '2006-01-27 10:54:12.000000', NULL, 1),
(2091849, 284690, 48890, '<td valign="top">Great still life.  I like the overall dark feeling, yet there is a lot of detail to look at.</td>', 'Great still life.  I like the overall dark feeling, yet there is a lot of detail to look at.', '2006-01-27 10:54:48.000000', NULL, 1),
(2091850, 284406, 43753, '<td valign="top">Nice colors. THe image is so uniform with its bisque and yellow, then there in the corner a sprinkle of pink. Outstanding.</td>', 'Nice colors. THe image is so uniform with its bisque and yellow, then there in the corner a sprinkle of pink. Outstanding.', '2006-01-27 10:55:06.000000', NULL, 1),
(2091852, 285705, 43753, '<td valign="top">Very gritty and dark - like the work itself. Nice image.</td>', 'Very gritty and dark - like the work itself. Nice image.', '2006-01-27 10:55:40.000000', NULL, 1),
(2091853, 284661, 48890, '<td valign="top">A wonderful portrait.  Love the composition and lighting.</td>', 'A wonderful portrait.  Love the composition and lighting.', '2006-01-27 10:55:44.000000', NULL, 1),
(2091856, 285338, 43753, '<td valign="top">I think Manny would be flattered. This is a beuatiful portrait, and I think you really captured Manny''s style with this one.</td>', 'I think Manny would be flattered. This is a beuatiful portrait, and I think you really captured Manny''s style with this one.', '2006-01-27 10:56:12.000000', NULL, 1),
(2091860, 284618, 43753, '<td valign="top">Poor thing - pretty in pink. Looks like you had fun cleaning up after this shoot!! I like the lighting and the pink. Very nice.</td>', 'Poor thing - pretty in pink. Looks like you had fun cleaning up after this shoot!! I like the lighting and the pink. Very nice.', '2006-01-27 10:56:55.000000', NULL, 1),
(2091861, 285313, 48890, '<td valign="top">Great composition.  It''s a  shame the faces are barely discernable; you should have used fill flash, IMO, to bring out more detail in shadows.</td>', 'Great composition.  It''s a  shame the faces are barely discernable; you should have used fill flash, IMO, to bring out more detail in shadows.', '2006-01-27 10:56:57.000000', NULL, 1),
(2091865, 283627, 43753, '<td valign="top">Wow! Amazing portrait. I love the technique used to achieve the effect. Lots of detail and very muted color. Love the eyes.</td>', 'Wow! Amazing portrait. I love the technique used to achieve the effect. Lots of detail and very muted color. Love the eyes.', '2006-01-27 10:57:43.000000', NULL, 1),
(2091867, 284595, 48890, '<td valign="top">A very drammatic shot, well composed and exposed</td>', 'A very drammatic shot, well composed and exposed', '2006-01-27 10:57:54.000000', NULL, 1),
(2091871, 284643, 43753, '<td valign="top">The directions here are amazing - your lines really make the image. I love the "feel" of the image with the couple walking with their shadows cast.</td>', 'The directions here are amazing - your lines really make the image. I love the "feel" of the image with the couple walking with their shadows cast.', '2006-01-27 10:58:30.000000', NULL, 1),
(2091875, 285632, 43753, '<td valign="top">Witkin! I was wondering when I would see a Witkin/ I think the focus is a little too soft.</td>', 'Witkin! I was wondering when I would see a Witkin/ I think the focus is a little too soft.', '2006-01-27 10:59:18.000000', NULL, 1),
(2091877, 285554, 43753, '<td valign="top">This is quite different. I love the intensity of the portrait.</td>', 'This is quite different. I love the intensity of the portrait.', '2006-01-27 10:59:42.000000', NULL, 1),
(2091883, 285353, 43753, '<td valign="top">You have a strange lighting situation twards the bottome of your image. I do like the colors, and your composition looks rather like a sun burst.</td>', 'You have a strange lighting situation twards the bottome of your image. I do like the colors, and your composition looks rather like a sun burst.', '2006-01-27 11:00:44.000000', NULL, 1),
(2091884, 285094, 43753, '<td valign="top">Nice architectural image with great use of line.</td>', 'Nice architectural image with great use of line.', '2006-01-27 11:01:07.000000', NULL, 1),
(2091886, 285451, 43753, '<td valign="top">Very original and clean. I love the electronic flow of the image. Great frame.</td>', 'Very original and clean. I love the electronic flow of the image. Great frame.', '2006-01-27 11:01:38.000000', NULL, 1),
(2091890, 284688, 43753, '<td valign="top">I ahve seen a lot of RGB photos recently. THis one is a nice addition. Very clean. Nice even backbround. Nice coloring.</td>', 'I ahve seen a lot of RGB photos recently. THis one is a nice addition. Very clean. Nice even backbround. Nice coloring.', '2006-01-27 11:02:38.000000', NULL, 1),
(2091896, 285627, 43753, '<td valign="top">Beautiful portrait. I like the the way the lighting lands across the subjects face. Her postitioning is excellent.</td>', 'Beautiful portrait. I like the the way the lighting lands across the subjects face. Her postitioning is excellent.', '2006-01-27 11:03:26.000000', NULL, 1),
(2091897, 285756, 43753, '<td valign="top">Smooth cityscape. Great lighting.</td>', 'Smooth cityscape. Great lighting.', '2006-01-27 11:03:47.000000', NULL, 1),
(2091900, 284447, 43753, '<td valign="top">Great work. I like the high contrast. It erally brings the details out in the face.</td>', 'Great work. I like the high contrast. It erally brings the details out in the face.', '2006-01-27 11:04:27.000000', NULL, 1),
(2091902, 284692, 43753, '<td valign="top">Soft feathery snow covered trees all in a row. Beautiful!</td>', 'Soft feathery snow covered trees all in a row. Beautiful!', '2006-01-27 11:04:50.000000', NULL, 1),
(2091911, 285469, 48890, '<td valign="top">Andrzej Dragan''s shots are a lot more drammatic than this.  He uses a lot of retouching techniques to enhance the shots.  You are trying to re-create the "portrait with dirty nails", and I think that your shot doesn''t even start to resemble the work of Dragan.  You captured what the camera saw, and he attempts to capture the opposite of that.  Sorry.  You picked a difficult photographer for a tribute, and IMO this doesn''t quite cut it.</td>', 'Andrzej Dragan''s shots are a lot more drammatic than this.  He uses a lot of retouching techniques to enhance the shots.  You are trying to re-create the "portrait with dirty nails", and I think that your shot doesn''t even start to resemble the work of Dragan.  You captured what the camera saw, and he attempts to capture the opposite of that.  Sorry.  You picked a difficult photographer for a tribute, and IMO this doesn''t quite cut it.', '2006-01-27 11:08:36.000000', NULL, 1),
(2091913, 283475, 48890, '<td valign="top">I think that you got Warhol''s style quite well!</td>', 'I think that you got Warhol''s style quite well!', '2006-01-27 11:09:20.000000', NULL, 1),
(2091922, 285735, 48890, '<td valign="top">Nice!  There is so much going on in this image.  The framing, the moment, and the story are perfect.  I wish there wasn''t the extra guy on the other side of the street in the reflection.   Other than that, it''s a great shot!</td>', 'Nice!  There is so much going on in this image.  The framing, the moment, and the story are perfect.  I wish there wasn''t the extra guy on the other side of the street in the reflection.   Other than that, it''s a great shot!', '2006-01-27 11:11:05.000000', NULL, 1),
(2091928, 284567, 48890, '<td valign="top">Yes, this is a good tribute to Dragan.  I just commented on another one, which didn''t quite make it, in my opinion, but this one I like a lot.</td>', 'Yes, this is a good tribute to Dragan.  I just commented on another one, which didn''t quite make it, in my opinion, but this one I like a lot.', '2006-01-27 11:13:23.000000', NULL, 1),
(2091929, 284027, 48890, '<td valign="top">Very well composed and executed.</td>', 'Very well composed and executed.', '2006-01-27 11:13:33.000000', NULL, 1),
(2091930, 285519, 48890, '<td valign="top">Nice shot.  There is a lot to look at.</td>', 'Nice shot.  There is a lot to look at.', '2006-01-27 11:13:39.000000', NULL, 1),
(2091934, 283962, 42638, '<td valign="top">Beautiful! Love the leading lines and curves. Well done!</td>', 'Beautiful! Love the leading lines and curves. Well done!', '2006-01-27 11:16:41.000000', NULL, 1),
(2091937, 284988, 42638, '<td valign="top">Wonderful tones here.</td>', 'Wonderful tones here.', '2006-01-27 11:17:31.000000', NULL, 1),
(2091938, 285094, 42638, '<td valign="top">Beautiful! Love the lines and perspective. Nice catch on the flag.</td>', 'Beautiful! Love the lines and perspective. Nice catch on the flag.', '2006-01-27 11:18:24.000000', NULL, 1),
(2091942, 285524, 42638, '<td valign="top">wow, so vast and simple. Very silent. Excellent!</td>', 'wow, so vast and simple. Very silent. Excellent!', '2006-01-27 11:18:53.000000', NULL, 1),
(2091944, 284990, 42638, '<td valign="top">Very nice, Love the vivid stark colors and hues.</td>', 'Very nice, Love the vivid stark colors and hues.', '2006-01-27 11:19:34.000000', NULL, 1),
(2091946, 285631, 42638, '<td valign="top">Nicely done. Love the framing of the 3 sides on this.</td>', 'Nicely done. Love the framing of the 3 sides on this.', '2006-01-27 11:20:02.000000', NULL, 1),
(2091949, 284886, 42638, '<td valign="top">Fantastic colors. Love the it moves your eyes. Nicely done.</td>', 'Fantastic colors. Love the it moves your eyes. Nicely done.', '2006-01-27 11:21:06.000000', NULL, 1),
(2091951, 285756, 42638, '<td valign="top">Fantastic city scene! Love the use of B&amp;W here. Very crisp focus</td>', 'Fantastic city scene! Love the use of B&W here. Very crisp focus', '2006-01-27 11:21:42.000000', NULL, 1),
(2091954, 283966, 42638, '<td valign="top">Nicely done, Love the simplicity of this one, Interesting how his hands form a heart right at the center of the picture.</td>', 'Nicely done, Love the simplicity of this one, Interesting how his hands form a heart right at the center of the picture.', '2006-01-27 11:22:43.000000', NULL, 1),
(2091984, 283627, 34659, '<td valign="top">By far, the best Dragan tribute.  Really outstanding portrait and editing.</td>', 'By far, the best Dragan tribute.  Really outstanding portrait and editing.', '2006-01-27 11:39:30.000000', NULL, 1),
(2091993, 284969, 34659, '<td valign="top">Great shot - and strong entry.  Certainly in the vein of Newton with subject placement, tonal range, lighting.  Nice job.</td>', 'Great shot - and strong entry.  Certainly in the vein of Newton with subject placement, tonal range, lighting.  Nice job.', '2006-01-27 11:42:43.000000', NULL, 1),
(2091996, 284171, 18197, '<td valign="top">Beautiful photo and nicely done in the style of the photographer. The rays of light are a very nice touch.</td>', 'Beautiful photo and nicely done in the style of the photographer. The rays of light are a very nice touch.', '2006-01-27 11:43:59.000000', NULL, 1),
(2092000, 285554, 48890, '<td valign="top">Great shot!  Very human and beautiful.</td>', 'Great shot!  Very human and beautiful.', '2006-01-27 11:46:32.000000', NULL, 1),
(2092022, 285599, 50695, '<td valign="top">from what I''ve seen, Steve Parish is more dramatic than this. (I prefer your style)</td>', 'from what I''ve seen, Steve Parish is more dramatic than this. (I prefer your style)', '2006-01-27 11:59:10.000000', NULL, 1),
(2092102, 285312, 48339, '<td valign="top">i suggest a lot less saturation of colors. is this a photograph or a work of digital art?? hmmm. too fake for me.</td>', 'i suggest a lot less saturation of colors. is this a photograph or a work of digital art?? hmmm. too fake for me.', '2006-01-27 12:27:03.000000', NULL, 1),
(2092143, 284618, 48339, '<td valign="top">great shot! but who''s the tribute to??  i can guess. i guess.</td>', 'great shot! but who''s the tribute to??  i can guess. i guess.', '2006-01-27 12:35:39.000000', NULL, 1),
(2092151, 285605, 33732, '<td valign="top">This is a nice composition.  Seems like Adams did not include much man made material.  The depth is nice.</td>', 'This is a nice composition.  Seems like Adams did not include much man made material.  The depth is nice.', '2006-01-27 12:36:49.000000', NULL, 1),
(2092152, 284159, 33732, '<td valign="top">Darks could be darker for more contrast.</td>', 'Darks could be darker for more contrast.', '2006-01-27 12:37:10.000000', NULL, 1),
(2092156, 285287, 33732, '<td valign="top">The red combo is nice.</td>', 'The red combo is nice.', '2006-01-27 12:37:44.000000', NULL, 1),
(2092160, 283628, 33732, '<td valign="top">From my review this is a good representation.</td>', 'From my review this is a good representation.', '2006-01-27 12:38:11.000000', NULL, 1),
(2092161, 285312, 49556, '<td valign="top">Wow! Just a loss for words.</td>', 'Wow! Just a loss for words.', '2006-01-27 12:38:36.000000', NULL, 1),
(2092166, 285675, 33732, '<td valign="top">Nature.  Expanse! Depth! Contrast coudl be increased, darker darks.  Good luck.</td>', 'Nature.  Expanse! Depth! Contrast coudl be increased, darker darks.  Good luck.', '2006-01-27 12:38:57.000000', NULL, 1),
(2092173, 285418, 33732, '<td valign="top">Good contrast.  Fits my Adams concept.  I don''t think of color when I see this and a lot of his work would have had color.</td>', 'Good contrast.  Fits my Adams concept.  I don''t think of color when I see this and a lot of his work would have had color.', '2006-01-27 12:41:31.000000', NULL, 1),
