(2092175, 284891, 33732, '<td valign="top">Subject is the same as Adams.  You compete with the Master too much.  Very nice composition.  More contrast is needed.</td>', 'Subject is the same as Adams.  You compete with the Master too much.  Very nice composition.  More contrast is needed.', '2006-01-27 12:43:36.000000', NULL, 1),
(2092177, 283947, 33732, '<td valign="top">Fits the challenge.  Good composition.  Why not show sky above the building?</td>', 'Fits the challenge.  Good composition.  Why not show sky above the building?', '2006-01-27 12:44:23.000000', NULL, 1),
(2092178, 283454, 33732, '<td valign="top">Simple and effective for the style.</td>', 'Simple and effective for the style.', '2006-01-27 12:44:43.000000', NULL, 1),
(2092180, 283739, 33732, '<td valign="top">Interesting.  The composition fits.</td>', 'Interesting.  The composition fits.', '2006-01-27 12:45:11.000000', NULL, 1),
(2092182, 284690, 33732, '<td valign="top">The objects help with this presentation.</td>', 'The objects help with this presentation.', '2006-01-27 12:45:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2092191, 284602, 33732, '<td valign="top">I review some work.  I like this for color.  The crop on the left distracts.  The lighting is effective.</td>', 'I review some work.  I like this for color.  The crop on the left distracts.  The lighting is effective.', '2006-01-27 12:47:11.000000', NULL, 1),
(2092194, 283852, 33732, '<td valign="top">Very effective lighting.</td>', 'Very effective lighting.', '2006-01-27 12:47:28.000000', NULL, 1),
(2092198, 285241, 33732, '<td valign="top">Depth. Contrast. Subjects.  Some clouds would be nice. Seems appropriate for Adams.</td>', 'Depth. Contrast. Subjects.  Some clouds would be nice. Seems appropriate for Adams.', '2006-01-27 12:48:26.000000', NULL, 1),
(2092209, 285451, 46634, '<td valign="top">Interesting!  Comes very close to actual prints.  I''d be interested to know how you did this. ;-)</td>', 'Interesting!  Comes very close to actual prints.  I''d be interested to know how you did this. ;-)', '2006-01-27 12:51:55.000000', NULL, 1),
(2092214, 284739, 33732, '<td valign="top">Very nice.</td>', 'Very nice.', '2006-01-27 12:52:29.000000', NULL, 1),
(2092217, 284882, 46634, '<td valign="top">Is this a picture OF a picture?  I could have sworn that was not allowed?</td>', 'Is this a picture OF a picture?  I could have sworn that was not allowed?', '2006-01-27 12:52:49.000000', NULL, 1),
(2092219, 283972, 33732, '<td valign="top">The clouds need better texture for Adams but very effective photo.</td>', 'The clouds need better texture for Adams but very effective photo.', '2006-01-27 12:53:15.000000', NULL, 1),
(2092221, 284990, 46634, '<td valign="top">The left side is a little too bright and distracting.  A softer yellow would have really nailed this one for me.</td>', 'The left side is a little too bright and distracting.  A softer yellow would have really nailed this one for me.', '2006-01-27 12:54:00.000000', NULL, 1),
(2092225, 285747, 48339, '<td valign="top">very nice, a top three finisher for me</td>', 'very nice, a top three finisher for me', '2006-01-27 12:54:20.000000', NULL, 1),
(2092226, 283134, 46634, '<td valign="top">a little too dark and out of focus slightly.</td>', 'a little too dark and out of focus slightly.', '2006-01-27 12:54:22.000000', NULL, 1),
(2092228, 285122, 46634, '<td valign="top">Interesting, but the glare on the face is a little too harsh.</td>', 'Interesting, but the glare on the face is a little too harsh.', '2006-01-27 12:54:41.000000', NULL, 1),
(2092229, 283627, 48339, '<td valign="top">a top three for me</td>', 'a top three for me', '2006-01-27 12:54:47.000000', NULL, 1),
