(2092231, 285332, 46634, '<td valign="top">I''m still trying to figure out what this is...........</td>', 'I''m still trying to figure out what this is...........', '2006-01-27 12:55:24.000000', NULL, 1),
(2092232, 285308, 46634, '<td valign="top">Focus appears to be on her shoulder strap.  A little too soft for me. That aside -  Lovely capture</td>', 'Focus appears to be on her shoulder strap.  A little too soft for me. That aside -  Lovely capture', '2006-01-27 12:55:42.000000', NULL, 1),
