(2092241, 284688, 33732, '<td valign="top">Great and color also.</td>', 'Great and color also.', '2006-01-27 12:57:03.000000', NULL, 1),
(2092243, 285589, 33732, '<td valign="top">This is effective.</td>', 'This is effective.', '2006-01-27 12:57:26.000000', NULL, 1),
