(2097903, 285492, 44611, '<td valign="top">Stunning work.  Am fascinated to learn more about how you created this.  Wish you good luck - this deserves high placing.</td>', 'Stunning work.  Am fascinated to learn more about how you created this.  Wish you good luck - this deserves high placing.', '2006-01-29 09:18:28.000000', NULL, 1),
(2097963, 284540, 21604, '<td valign="top">I wish I knew who this was a tribute too.  My main problem with this is that it looks more like an image drawn in paintshop pro rather than a photograph.  Although there are filters I think that would get this effect. I''d like to see one from the original photographer so I could compare.</td>', 'I wish I knew who this was a tribute too.  My main problem with this is that it looks more like an image drawn in paintshop pro rather than a photograph.  Although there are filters I think that would get this effect. I''d like to see one from the original photographer so I could compare.', '2006-01-29 10:07:11.000000', NULL, 1),
(2097969, 283134, 21604, '<td valign="top">This is a nice dark shot, but having the foreground so out of focus doesn''t work for me. If I could see a shot done by the photog this is a tribute to I may be able to get a better sense of why this was done this way.</td>', 'This is a nice dark shot, but having the foreground so out of focus doesn''t work for me. If I could see a shot done by the photog this is a tribute to I may be able to get a better sense of why this was done this way.', '2006-01-29 10:08:50.000000', NULL, 1),
(2098131, 285492, 45559, '<td valign="top">This photo is astonishing.The way I look at it, must be Graphicfunk''s(hope i''m not wrong).Anyway this is my choice for blue.10</td>', 'This photo is astonishing.The way I look at it, must be Graphicfunk''s(hope i''m not wrong).Anyway this is my choice for blue.10', '2006-01-29 11:22:56.000000', NULL, 1),
(2098154, 285492, 6804, '<td valign="top">Aaaah, you''ve exposed the inside workings of your creative mind here.<br/> <br/>As usual, excellent entry Daniel.   10</td>', 'Aaaah, you''ve exposed the inside workings of your creative mind here. As usual, excellent entry Daniel.   10', '2006-01-29 11:38:04.000000', NULL, 1),
