(2099713, 284692, 52255, '<td valign="top">Interesting use of the grey scale.  Uses depth of field wisely.  Makes you feel like you are a part of the picture, even in the black and white.  Something I might see near my home.</td>', 'Interesting use of the grey scale.  Uses depth of field wisely.  Makes you feel like you are a part of the picture, even in the black and white.  Something I might see near my home.', '2006-01-29 22:34:16.000000', NULL, 1),
(2099729, 283159, 52255, '<td valign="top">The blues are gorgeous, looks like it would be very soft to the touch.  I like the light and dark all in the same color hue and saturation.</td>', 'The blues are gorgeous, looks like it would be very soft to the touch.  I like the light and dark all in the same color hue and saturation.', '2006-01-29 22:37:06.000000', NULL, 1),
(2099744, 285354, 52255, '<td valign="top">Great use of clothing color to set backdrop, very representative of what anne geddes would do.  I like it.</td>', 'Great use of clothing color to set backdrop, very representative of what anne geddes would do.  I like it.', '2006-01-29 22:38:59.000000', NULL, 1),
