(2107064, 283699, 52108, '<td valign="top">Nice Capture !</td>', 'Nice Capture !', '2006-01-31 22:07:42.000000', NULL, 1),
(2107185, 284864, 32001, '<td valign="top">I don''t really care for the blured style, but you did a good job emulating the style referenced.</td>', 'I don''t really care for the blured style, but you did a good job emulating the style referenced.', '2006-01-31 22:36:48.000000', NULL, 1),
(2107213, 283972, 41574, '<td valign="top">I''ve seen a lot of "Ansel-Adams"es, so far, but this one stands out as one of the better ones. Good job.</td>', 'I''ve seen a lot of "Ansel-Adams"es, so far, but this one stands out as one of the better ones. Good job.', '2006-01-31 22:41:24.000000', NULL, 1),
(2107219, 284988, 41574, '<td valign="top">I think Mapplethorpe would be a bit more "in-your-face," and perhaps less "artsy," but this is a great photograph, nonetheless.</td>', 'I think Mapplethorpe would be a bit more "in-your-face," and perhaps less "artsy," but this is a great photograph, nonetheless.', '2006-01-31 22:42:12.000000', NULL, 1),
(2107301, 285750, 22734, '<td valign="top">Deeply flattered. 7 for a good effort.</td>', 'Deeply flattered. 7 for a good effort.', '2006-01-31 23:05:46.000000', NULL, 1),
(2107304, 285312, 32001, '<td valign="top">Beautiful color &amp; detail.  Bumping up.</td>', 'Beautiful color & detail.  Bumping up.', '2006-01-31 23:06:30.000000', NULL, 1),
(2107312, 283627, 32001, '<td valign="top">Great job emulating Dragans edgy style.  Bumping up.</td>', 'Great job emulating Dragans edgy style.  Bumping up.', '2006-01-31 23:08:52.000000', NULL, 1),
(2107374, 285554, 50695, '<td valign="top">beautiful portrait. this kid knows something I don''t. 9.</td>', 'beautiful portrait. this kid knows something I don''t. 9.', '2006-01-31 23:21:34.000000', NULL, 1),
(2107378, 285492, 50695, '<td valign="top">I think this captures the spirit and playfulness of Man Ray very well. 9.</td>', 'I think this captures the spirit and playfulness of Man Ray very well. 9.', '2006-01-31 23:22:10.000000', NULL, 1),
(2107381, 283627, 24454, '<td valign="top">Has to be Lesley Goodman ???    It has to be because I fell in love with this picture the minute I saw it.   Another one straight to my favorites folder!    And probably another ribbon!   I hope so!  10</td>', 'Has to be Lesley Goodman ???    It has to be because I fell in love with this picture the minute I saw it.   Another one straight to my favorites folder!    And probably another ribbon!   I hope so!  10', '2006-01-31 23:22:47.000000', NULL, 1),
(2107382, 285241, 50695, '<td valign="top">That floor of lilies is stunning. It looks like glass over marble. 9.</td>', 'That floor of lilies is stunning. It looks like glass over marble. 9.', '2006-01-31 23:22:59.000000', NULL, 1),
(2107386, 284031, 50695, '<td valign="top">a fitting member of Jim Dratfield''s pound. Great personality in your subject.</td>', 'a fitting member of Jim Dratfield''s pound. Great personality in your subject.', '2006-01-31 23:23:35.000000', NULL, 1),
(2107387, 285345, 50695, '<td valign="top">this is daring of you, to use pop/ad imagery not associated with this photographer. What is associated with this photographer, is a picture that tells a story, a sense of "oh!" where things fit or don''t fit in a very definite way. 9.</td>', 'this is daring of you, to use pop/ad imagery not associated with this photographer. What is associated with this photographer, is a picture that tells a story, a sense of "oh!" where things fit or don''t fit in a very definite way. 9.', '2006-01-31 23:23:40.000000', NULL, 1),
(2107389, 284988, 50695, '<td valign="top">great suggestiveness by the use of hands. a heterosexual mapplethorpe. 9.</td>', 'great suggestiveness by the use of hands. a heterosexual mapplethorpe. 9.', '2006-01-31 23:24:14.000000', NULL, 1),
(2107393, 285117, 30861, '<td valign="top">Makes me chuckle. Hard to imagine doing Parkinson much better, really. Good luck!</td>', 'Makes me chuckle. Hard to imagine doing Parkinson much better, really. Good luck!', '2006-01-31 23:24:47.000000', NULL, 1),
(2107415, 285733, 50695, '<td valign="top">one of my favorite of the many ansel adams tributes. The fog hides the mountains and makes them more mysterious and glorious. 9.</td>', 'one of my favorite of the many ansel adams tributes. The fog hides the mountains and makes them more mysterious and glorious. 9.', '2006-01-31 23:29:21.000000', NULL, 1),
(2107419, 285423, 50695, '<td valign="top">If I saw this in an Ansel Adams book, it wouldn''t stand out. I would readily accept it. You fulfilled the challenge well, as far as I''m concerned.</td>', 'If I saw this in an Ansel Adams book, it wouldn''t stand out. I would readily accept it. You fulfilled the challenge well, as far as I''m concerned.', '2006-01-31 23:30:04.000000', NULL, 1),
(2107435, 285434, 50695, '<td valign="top">This is wonderful. Great texture. It looks like it''s all about to disappear. It''s all been a dream.</td>', 'This is wonderful. Great texture. It looks like it''s all about to disappear. It''s all been a dream.', '2006-01-31 23:31:50.000000', NULL, 1),
(2107438, 285354, 50695, '<td valign="top">well, after looking thru dozens of anne geddes photos of babies, I don''t think she would take this shot. She likes to enclose babies, remind us of how small they are. Your picture makes the baby look grand, even hints at the power this baby will grow into. For that reason, I think you''ve achieved something more profound, even though geddes'' technique and eye are very impressive. So I put this under influence, rather than mere imitation. Good work.</td>', 'well, after looking thru dozens of anne geddes photos of babies, I don''t think she would take this shot. She likes to enclose babies, remind us of how small they are. Your picture makes the baby look grand, even hints at the power this baby will grow into. For that reason, I think you''ve achieved something more profound, even though geddes'' technique and eye are very impressive. So I put this under influence, rather than mere imitation. Good work.', '2006-01-31 23:31:59.000000', NULL, 1),
(2107440, 284470, 50695, '<td valign="top">From what I''ve googled of Plossu, he creates striking abstract patterns, unlike what you''ve achieved here. I do, however, like your photograph for its own merits. The cutting off of the head to be replaced by a pile of books is simply brilliant.</td>', 'From what I''ve googled of Plossu, he creates striking abstract patterns, unlike what you''ve achieved here. I do, however, like your photograph for its own merits. The cutting off of the head to be replaced by a pile of books is simply brilliant.', '2006-01-31 23:32:03.000000', NULL, 1),
(2107443, 284836, 50695, '<td valign="top">I was disappointed to see a Warhol portrait so similar to this one. You are more arch, though (literally), and your hand gesture is even more phallic than his. I''ll give you some points for that. :)</td>', 'I was disappointed to see a Warhol portrait so similar to this one. You are more arch, though (literally), and your hand gesture is even more phallic than his. I''ll give you some points for that. :)', '2006-01-31 23:32:24.000000', NULL, 1),
(2107445, 283852, 50695, '<td valign="top">this looks like a detail of a Sally Mann photograph, and the child doesn''t look adult enough. But still, very expressive and a striking photo on its own merits. Enjoyed.</td>', 'this looks like a detail of a Sally Mann photograph, and the child doesn''t look adult enough. But still, very expressive and a striking photo on its own merits. Enjoyed.', '2006-01-31 23:32:37.000000', NULL, 1),
(2107448, 285758, 50695, '<td valign="top">I think this is the best Weston. Other people took objects that he''d already photographed and did a less interesting job on them. You found something new and photographed it the way he did. Of course, in my ignorance, he might very well have tape dispenser shots. But my ignorance is your bliss. ;)</td>', 'I think this is the best Weston. Other people took objects that he''d already photographed and did a less interesting job on them. You found something new and photographed it the way he did. Of course, in my ignorance, he might very well have tape dispenser shots. But my ignorance is your bliss. ;)', '2006-01-31 23:32:58.000000', NULL, 1),
(2107451, 285640, 50695, '<td valign="top">Good choice to get a deformed pepper. Weston would''ve liked it.</td>', 'Good choice to get a deformed pepper. Weston would''ve liked it.', '2006-01-31 23:33:25.000000', NULL, 1),
(2107464, 285519, 50695, '<td valign="top">this captures kertesz''s love of geometry well. seems more "authentic" to me than the other kertesz.</td>', 'this captures kertesz''s love of geometry well. seems more "authentic" to me than the other kertesz.', '2006-01-31 23:34:35.000000', NULL, 1);
